<script lang="ts">
 import {onMount} from 'svelte';
 import {api,setCSRF,stamp,type Row} from '$lib/api';
 let auth:Row={};let state:Row={};let settings:Row={};let audit:Row[]=[];let tab='overview';let search='';let busy=false;let error='';let success='';let live=false;let elevatedUntil=0;
 let email='';let password='';let otp='';let code='';let loginMode='';let elevatedPassword='';let elevatedOTP='';let elevation=false;let editor:Row={};let form='';let editID='';let json='';let enrollment:Row|null=null;let appID='';let appKey='';let webhookSecret='';let groupName='Fleet';let groupOrganization='';let groupRepos:number[]=[];let sshHost='';let sshUser='';let sshKey='';let rootPassword='';let fingerprint='';let machineName='';let backupRetention=30;let backupInterval=24;let backupPassword='';let backupAccess='';let backupSecret='';let backupEndpoint='';let backupBucket='';let recoveryCodes:string[]=[];let totpSecret='';let migrationPreview:Row|null=null;let workflowID='';let jobID='';let migrationLabels='self-hosted,linux,x64';let logs='';let selectedInstallation=0;
 const nav=[['overview','Visão geral','◈'],['repositories','Repositórios','▤'],['workflows','Migração','⇄'],['machines','Máquinas','▣'],['pools','Pools','◉'],['jobs','Jobs','▷'],['alerts','Alertas','△'],['audit','Auditoria','≡'],['settings','Configurações','⚙']];
 const rows=(kind:string):Row[]=>state[kind]||[];
 const filtered=(kind:string)=>rows(kind).filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase()));
 const active=()=>rows('instances').filter(v=>!['removed','failed'].includes(v.state));
 const duration=(j:Row)=>j.started_at&&j.completed_at?Math.round((Date.parse(j.completed_at)-Date.parse(j.started_at))/1000)+'s':'—';
 async function run(fn:()=>Promise<void>){busy=true;error='';success='';try{await fn()}catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
 async function reload(){state=await api('/state');settings=await api('/settings');}
 async function start(){auth=await api('/auth/status');setCSRF(auth.csrf||'');if(auth.authenticated){await reload();const source=new EventSource('/api/events');source.addEventListener('state',e=>{state=JSON.parse((e as MessageEvent).data);live=true});source.onerror=()=>{live=false};return ()=>source.close();}}
 onMount(()=>{let dispose:(()=>void)|undefined;run(async()=>{dispose=await start()});return ()=>dispose?.()});
 async function login(){await run(async()=>{if(auth.setup_required&&loginMode!=='recover'){await api('/auth/setup','POST',{code,email,password});auth.setup_required=false;success='Administrador criado. Faça login.';return}if(loginMode==='recover'){await api('/auth/recover','POST',{code,password});loginMode='';success='Senha redefinida. Faça login.';return}const v=await api('/auth/login','POST',{email,password,otp});setCSRF(v.csrf);password='';otp='';await start()})}
 async function reauth(){await run(async()=>{await api('/auth/reauth','POST',{password:elevatedPassword,otp:elevatedOTP});elevatedUntil=Date.now()+5*60*1000;elevatedPassword='';elevatedOTP='';elevation=false;success='Operações sensíveis liberadas por 5 minutos.'})}
 async function switchTab(v:string){tab=v;search='';if(v==='audit')await run(async()=>{audit=await api('/audit')})}
 function openForm(kind:string,item?:Row){form=kind;editID=item?.id||'';const data=kind==='pool'?item||{name:'Linux builds',installation:selectedInstallation||rows('installation')[0]?.id||0,scope:'org',target:'',group:'',labels:['self-hosted','linux','x64'],arch:'amd64',image:'registry.example/runner-fleet-base@sha256:…',execution:'container',runner_version:'',runner_sha256_amd64:'',runner_sha256_arm64:'',machines:rows('machine').filter(m=>!m.cloud_provider).map(m=>m.id),min:0,max:2,weight:1,cpu:1,memory_mb:2048,disk_mb:4096,enabled:false,trusted:false,docker_sidecar:false,docker_image:'',spot:null}:item?{name:item.name,max_slots:item.max_slots,cpu:item.cpu,memory_mb:item.memory_mb,disk_mb:item.disk_mb,shared:item.shared,timezone:item.timezone,start_hour:item.start_hour,end_hour:item.end_hour}:{};editor=JSON.parse(JSON.stringify(data));if(kind==='pool'&&!editor.execution)editor.execution='container';json=JSON.stringify(editor,null,2)}
 function toggleSpot(){if(editor.spot){editor.spot=null;return}editor.spot={region:'us-east-1',image_id:'ami-',image_mode:'bootstrap',subnet_ids:[],security_group_ids:[],instance_profile:'',spot_instance_types:['m7i.large'],on_demand_instance_types:[],slots_per_machine:1,max_machines:4,idle_minutes:10,root_volume_gib:40,fallback_after_seconds:0}}
 async function saveForm(){if(form==='pool'&&(editor.spot||rows('pool').some((p:Row)=>p.id===editID&&p.spot))&&Date.now()>=elevatedUntil){elevation=true;error='Reautentique-se antes de alterar a configuração AWS/Spot.';return}await run(async()=>{const v=editor;await api(form==='pool'?'/pools'+(editID?'/'+editID:''):'/machines/'+editID,editID?'PUT':'POST',v);form='';await reload();success='Configuração salva.'})}
 async function action(path:string,body?:unknown){await run(async()=>{await api(path,'POST',body);await reload();success='Operação solicitada.'})}
 async function newCode(){await run(async()=>{enrollment=await api('/enrollment','POST',{});form='enrollment'})}
 async function scan(){await action('/github/scan',{installation:Number(selectedInstallation)})}
 async function previewMigration(w:Row,j:Row){workflowID=w.id;jobID=j.id;await run(async()=>{migrationPreview=await api('/github/migration','POST',{workflow:w.id,job:j.id,labels:migrationLabels.split(',').map(x=>x.trim()),sha:w.sha,create_pr:false});form='migration'})}
 async function createPR(){const w=rows('workflow').find(x=>x.id===workflowID);await run(async()=>{const v=await api('/github/migration','POST',{workflow:workflowID,job:jobID,labels:migrationLabels.split(',').map(x=>x.trim()),sha:w?.sha,create_pr:true});success='PR criado: '+v.url;form=''})}
 async function configureBackup(){await run(async()=>{await api('/backups/config','PUT',{enabled:true,endpoint:backupEndpoint,region:'auto',bucket:backupBucket,prefix:'backups',access_key:backupAccess,secret_key:backupSecret,password:backupPassword,retention_days:backupRetention,interval_hours:backupInterval});backupPassword='';backupAccess='';backupSecret='';success='Backup configurado. Guarde a senha e o recovery kit.'})}
 async function showLogs(j:Row){await run(async()=>{const r=await fetch('/api/jobs/'+j.id+'/logs');logs=await r.text();if(!r.ok)throw Error(logs);form='logs'})}
</script>
<svelte:head><title>Runner Fleet · Controle de execução</title><meta name="description" content="Gerencie seus runners do GitHub Actions em máquinas Linux."/></svelte:head>
{#if !auth.authenticated}
 <main class="auth"><div class="auth-card"><div class="brand"><span class="brand-icon">RF</span> Runner Fleet</div><p class="eyebrow">SEU CÓDIGO. SUA CAPACIDADE.</p><h1>{loginMode==='recover'?'Recuperar acesso':auth.setup_required?'Prepare sua central':'Bem-vindo de volta'}</h1><p class="muted">{auth.setup_required?'Use o código emitido no servidor para criar o primeiro administrador.':'Acesse suas máquinas, pools e execuções.'}</p><form onsubmit={e=>{e.preventDefault();login()}}>{#if auth.setup_required||loginMode==='recover'}<label>Código de uso único<input bind:value={code} autocomplete="off" required/></label>{/if}{#if loginMode!=='recover'}<label>Email<input type="email" bind:value={email} autocomplete="username" required/></label>{/if}<label>Senha<input type="password" bind:value={password} minlength={auth.setup_required||loginMode==='recover'?12:1} autocomplete="current-password" required/></label>{#if !auth.setup_required&&loginMode!=='recover'}<label>Código TOTP ou de recuperação<input bind:value={otp} autocomplete="one-time-code"/></label>{/if}<button class="primary" disabled={busy}>{busy?'Aguarde…':auth.setup_required?'Criar administrador':'Continuar'}</button></form><button class="text" onclick={()=>loginMode=loginMode==='recover'?'':'recover'}>Recuperação por código da CLI</button>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if success}<p class="success">{success}</p>{/if}</div></main>
{:else}
 <div class="shell"><aside><div class="brand"><span class="brand-icon">RF</span> Runner Fleet</div><p class="workspace">SELF-HOSTED CONTROL</p><nav>{#each nav as [key,label,icon]}<button class:active={tab===key} onclick={()=>switchTab(key)}><span>{icon}</span>{label}{#if key==='alerts'&&rows('alert').filter(a=>!a.acknowledged).length}<b>{rows('alert').filter(a=>!a.acknowledged).length}</b>{/if}</button>{/each}</nav><div class="sidebar-bottom"><span class:connected={live} class="dot"></span>{live?'Atualização ao vivo':'Reconectando'}<small>Linux · x64 / ARM64</small></div></aside><main class="content"><header><div><p class="eyebrow">RUNNER FLEET / {nav.find(n=>n[0]===tab)?.[1].toUpperCase()}</p><h1>{nav.find(n=>n[0]===tab)?.[1]}</h1></div><div class="header-actions"><button onclick={()=>elevation=true}>Reautenticar</button><button onclick={()=>run(async()=>{await api('/auth/logout','POST',{});location.reload()})}>Sair</button></div></header>
 {#if error}<div class="notice error" role="alert">{error}<button onclick={()=>error=''}>×</button></div>{/if}{#if success}<div class="notice success">{success}<button onclick={()=>success=''}>×</button></div>{/if}
 {#if tab==='overview'}
 <section class="hero"><div><span class="tag">CAPACIDADE SOB CONTROLE</span><h2>Suas máquinas.<br/>Uma central de execução.</h2><p>Conecte o GitHub, descubra os destinos dos jobs e ofereça capacidade onde ela faz falta.</p></div><button class="primary" onclick={newCode}>+ Adicionar máquina</button></section><div class="stats"><article><span>Máquinas online</span><strong>{rows('machine').filter(m=>m.state==='online').length}<small> / {rows('machine').length}</small></strong></article><article><span>Slots reservados</span><strong>{active().length}</strong></article><article><span>Jobs na fila</span><strong>{rows('job').filter(j=>j.status==='queued').length}</strong></article><article><span>Repositórios descobertos</span><strong>{rows('repository').length}</strong></article></div>
 <div class="grid2"><section class="panel"><h2>Consumo observado</h2><div class="machine-stats"><span><b>{state.analytics?.hosted_minutes||0}</b> minutos hospedados</span><span><b>{state.analytics?.self_hosted_minutes||0}</b> minutos próprios</span><span><b>{state.analytics?.peak_concurrency||0}</b> pico simultâneo</span></div><small>Estimativa hospedada: {state.analytics?.estimated_hosted_cost||0} · configure preço e referência nas preferências.</small><hr/><h2>Comece por aqui</h2><ol class="steps"><li><b>Conecte o GitHub</b><span>Configure a App e descubra instalações.</span><button onclick={()=>switchTab('settings')}>Configurar</button></li><li><b>Faça o inventário</b><span>Saiba o que os workflows pedem.</span><button onclick={()=>switchTab('repositories')}>Descobrir</button></li><li><b>Disponibilize capacidade</b><span>Cadastre máquinas e crie pools.</span><button onclick={()=>switchTab('pools')}>Ver pools</button></li></ol></section><section class="panel"><h2>Saúde da frota</h2>{#if rows('machine').length===0}<div class="empty">Nenhuma máquina cadastrada.<small>O agente conecta por saída HTTPS, sem abrir SSH público.</small></div>{/if}{#each rows('machine') as m}<div class="row"><div><b>{m.name}</b><small>{m.arch} · {stamp(m.last_seen)}</small></div><span class="badge" class:good={m.state==='online'}>{m.state}</span></div>{/each}</section></div>
 {:else if tab==='repositories'}
 <section class="panel"><div class="toolbar"><h2>Conexões GitHub</h2><button disabled={busy} onclick={()=>action('/github/refresh',{})}>Atualizar instalações</button></div><p class="muted">Acesso limitado aos repositórios selecionados na GitHub App. Nenhum workflow é modificado no inventário.</p><div class="toolbar"><select bind:value={selectedInstallation}><option value={0}>Selecione a instalação</option>{#each rows('installation') as i}<option value={i.id}>{i.owner} · #{i.id}{i.active===false?' (revogada)':''}</option>{/each}</select><button class="primary" disabled={busy||!selectedInstallation} onclick={scan}>Executar inventário</button><button disabled={!selectedInstallation} onclick={()=>{groupOrganization=rows('installation').find(i=>i.id===Number(selectedInstallation))?.owner||'';form='group'}}>Criar grupo restrito</button></div>{#each rows('scan') as scan}<div class="notice"><b>#{scan.installation} · {scan.state}</b><span>{scan.repositories||0} repositórios · {scan.jobs||0} jobs · {stamp(scan.finished)}</span>{#if scan.errors?.length}<details><summary>{scan.errors.length} lacunas de cobertura</summary>{#each scan.errors as msg}<p>{msg}</p>{/each}</details>{/if}</div>{/each}</section>
 <section class="panel"><h2>Runners e grupos existentes</h2>{#each rows('runner') as r}<details><summary>{r.target} · {r.scope} · {r.data?.runners?.length||0} runners</summary><pre>{JSON.stringify(r.data,null,2)}</pre></details>{/each}{#each rows('group') as g}<details><summary>Grupos de {g.target}</summary><pre>{JSON.stringify(g.data,null,2)}</pre></details>{/each}</section><div class="toolbar"><h2>Repositórios</h2><input class="search" placeholder="Filtrar repositórios…" bind:value={search}/></div><section class="panel table-wrap"><table><thead><tr><th>Repositório</th><th>Visibilidade</th><th>Branch</th><th>Observado</th></tr></thead><tbody>{#each filtered('repository') as r}<tr><td><a href={r.html_url} target="_blank" rel="noreferrer">{r.full_name}</a></td><td>{r.private?'Privado':'Público'}</td><td>{r.default_branch}</td><td>{stamp(r.observed_at)}</td></tr>{/each}</tbody></table>{#if !rows('repository').length}<div class="empty">Execute o inventário após conectar a App.</div>{/if}</section>
 {:else if tab==='workflows'}
 <div class="toolbar"><p class="muted">Diagnóstico baseado em arquivos e execuções observadas.</p><input class="search" placeholder="Filtrar workflow ou repo…" bind:value={search}/></div><label>Labels para proposta de migração<input bind:value={migrationLabels}/></label>{#each filtered('workflow') as w}<section class="panel"><div class="toolbar"><h2>{w.repository}</h2><span class="badge">{w.ref}</span></div><p class="muted">{w.path} · SHA {w.sha?.slice(0,10)}</p>{#each w.jobs||[] as j}<div class="row"><div><b>{j.id}</b><small>{j.labels?.join(' + ')||j.reusable||'Destino não resolvido'}</small><small>{j.reason}</small></div><div class="actions"><span class="badge">{j.status}</span><button disabled={busy||j.status==='unresolved'||j.status==='matrix'||j.group} onclick={()=>previewMigration(w,j)}>Revisar alteração</button></div></div>{/each}</section>{/each}{#if !rows('workflow').length}<div class="empty">Nenhum workflow analisado ainda.<small>Expressões não resolvidas serão identificadas; não substituídas automaticamente.</small></div>{/if}
  {:else if tab==='machines'}
  <section class="panel machine-guide"><h2>Guia: instalar e validar um agente</h2><ol class="steps"><li><b>Prepare o host</b><span>Linux x64/ARM64, systemd, cgroup v2 e saída HTTPS para o painel e GitHub. O instalador prepara pacotes apt, rpm ou zypper. Pools de container ainda precisam de Docker rootless para <code>fleet-agent</code>. Pools de serviço persistente usam o usuário <code>fleet-runner</code>, sem sudo e sem Docker.</span></li><li><b>Cadastre por comando ou SSH privado</b><span>O código é de uso único e expira em 15 minutos. Para SSH, o painel precisa alcançar um IP privado/Tailscale e validar o fingerprint. O usuário pode ser root, ter <code>sudo -n</code>, ou informar a senha de root só para <code>su -</code>. Essa senha não é armazenada.</span></li><li><b>Confirme a prontidão antes do pool</b><span>Espere a máquina aparecer como <code>online</code> e o Doctor ficar aprovado. Abra “Telemetria e diagnóstico” se houver erro. Depois crie um pool pausado e faça um canário.</span></li></ol><p class="warning">Workers EC2 Spot são provisionados pelo Fleet quando configurados em um pool. O operador fornece permissões AWS, AMI, subnets, security groups e instance profile; o aviso de interrupção inicia drain best-effort, mas jobs ativos ainda podem ser perdidos.</p><p class="muted">O script <code>scripts/setup-rootless-docker.sh</code> está no checkout do projeto. Revise-o e a política da sua distro antes de executá-lo; ele usa o instalador oficial do Docker.</p></section>
  <div class="toolbar"><input class="search" placeholder="Filtrar máquinas…" bind:value={search}/><div class="actions"><button onclick={()=>form='ssh'}>Instalar por SSH privado</button><button class="primary" onclick={newCode}>+ Cadastro por comando</button></div></div><div class="cards">{#each filtered('machine') as m}<section class="panel"><div class="toolbar"><h2>{m.name}</h2><span class="badge" class:good={m.state==='online'}>{m.state}</span></div><p class="muted">{m.arch} · {m.shared?'Compartilhada':'Dedicada'} · {m.id.slice(0,8)}</p><div class="machine-stats"><span><b>{m.max_slots}</b> slots</span><span><b>{m.cpu}</b> CPU</span><span><b>{m.memory_mb}</b> MB</span></div><p class="muted">Último contato: {stamp(m.last_seen)}</p><p class:success={m.doctor?.ready||m.doctor?.service_ready} class:error={m.doctor&&!m.doctor.ready&&!m.doctor.service_ready}>{m.doctor?.ready?'Docker rootless pronto. ':''}{m.doctor?.service_ready?'Runner persistente pronto.':''}{!m.doctor?.ready&&!m.doctor?.service_ready?(m.doctor?.error||'Aguardando doctor'):''}</p><details><summary>Telemetria e diagnóstico</summary><pre>{JSON.stringify({doctor:m.doctor,telemetry:m.telemetry},null,2)}</pre></details><div class="actions wrap"><button onclick={()=>openForm('machine',m)}>Configurar</button><button onclick={()=>action('/machines/'+m.id+'/doctor',{})}>Doctor</button><button onclick={()=>action('/machines/'+m.id+'/'+(m.state==='draining'?'resume':'drain'),{})}>{m.state==='draining'?'Retomar':'Drenar'}</button><button onclick={()=>{const url=prompt('Diretório HTTPS da release assinada (após drain)',location.origin+'/downloads');if(url)action('/machines/'+m.id+'/update',{url})}}>Atualizar</button><button class="danger" onclick={()=>{if(confirm('Revogar identidade? A máquina perderá acesso e reservas serão preservadas até reconciliação.'))action('/machines/'+m.id+'/revoke',{})}}>Revogar</button></div></section>{/each}</div>{#if !rows('machine').length}<div class="empty">Cadastre sua primeira máquina Linux.</div>{/if}
 {:else if tab==='pools'}
 <div class="toolbar"><p class="muted">O GitHub atribui jobs. A plataforma distribui a capacidade oferecida.</p><button class="primary" onclick={()=>openForm('pool')}>+ Criar pool</button></div><div class="cards">{#each rows('pool') as p}<section class="panel"><div class="toolbar"><h2>{p.name}</h2><span class="badge" class:good={p.enabled}>{p.enabled?'Ativo':'Pausado'}</span></div><p>{p.target} <span class="muted">· {p.scope}</span></p><div class="chips">{#each p.labels as l}<span class="badge">{l}</span>{/each}</div><div class="machine-stats"><span><b>{active().filter(i=>i.pool===p.id).length}/{p.max}</b> slots</span><span><b>{p.cpu}</b> CPU/job</span><span><b>{p.memory_mb}</b> MB/job</span></div><p class="muted">{p.arch} · peso {p.weight} · {p.execution==='service'?'serviço persistente':'container efêmero'} · {p.machines?.length||0} máquinas{p.spot?' · EC2 Spot / On-Demand opcional':''}</p>{#if p.spot}<p class="muted">{rows('spot_launch').filter((launch:Row)=>launch.pool===p.id).length} launches cloud registrados</p>{#each rows('spot_launch').filter((launch:Row)=>launch.pool===p.id).slice(0,3) as launch}<small>EC2 {launch.instance_type} · {launch.market} · {launch.state}{launch.error_code?' · '+launch.error_code:''}</small>{/each}{/if}<div class="actions"><button onclick={()=>openForm('pool',p)}>Editar</button><button onclick={()=>p.spot?openForm('pool',{...p,enabled:!p.enabled}):run(async()=>{await api('/pools/'+p.id,'PUT',{...p,enabled:!p.enabled});await reload()})}>{p.enabled?'Pausar':'Ativar'}</button><button class="danger" onclick={()=>run(async()=>{if(confirm('Excluir pool sem instâncias ativas?')){await api('/pools/'+p.id,'DELETE');await reload()}})}>Excluir</button></div></section>{/each}</div>{#if !rows('pool').length}<div class="empty">Nenhum pool.<small>Cadastre uma máquina e configure um escopo com labels explícitas.</small></div>{/if}<section class="panel"><h2>Instâncias e reservas</h2>{#each rows('instances').slice(0,30) as v}<div class="row"><div><b>{v.name}</b><small>{v.pool} · {v.state}{v.error?' · '+v.error:''}</small></div><button onclick={()=>{logs=rows('agentlog').find(l=>l.id===v.id)?.log||'Nenhum log do runner recebido.';form='logs'}}>Diagnóstico</button>{#if !['removed','failed'].includes(v.state)}<button onclick={()=>action('/instances/'+v.id+'/drain',{})}>Drenar</button>{/if}</div>{/each}</section>
 {:else if tab==='jobs'}
 <div class="toolbar"><p class="muted">Execuções observadas no GitHub; duração não equivale à cobrança.</p><input class="search" placeholder="Filtrar jobs…" bind:value={search}/></div><section class="panel table-wrap"><table><thead><tr><th>Job / repositório</th><th>Status</th><th>Runner observado</th><th>Duração</th><th></th></tr></thead><tbody>{#each filtered('job') as j}<tr><td><b>{j.name}</b><small>{j.repository}</small><small>{j.labels?.join(', ')}</small>{#if j.queue_reason}<small class="warning">{j.queue_reason}</small>{/if}</td><td><span class="badge" class:good={j.conclusion==='success'}>{j.conclusion||j.status}</span></td><td>{j.runner_name||'Ainda não atribuído'}</td><td>{duration(j)}</td><td><button onclick={()=>showLogs(j)}>Logs</button></td></tr>{/each}</tbody></table>{#if !rows('job').length}<div class="empty">Sem jobs observados no período.</div>{/if}</section>
 {:else if tab==='alerts'}
 {#each rows('alert') as a}<section class="panel"><div class="toolbar"><h2>{a.title}</h2><span class="badge">{a.acknowledged?'Reconhecido':'Aberto'}</span></div><p>{a.message}</p><small>{stamp(a.created)}</small>{#if !a.acknowledged}<button onclick={()=>action('/alerts/'+encodeURIComponent(a.id)+'/ack',{})}>Reconhecer</button>{/if}</section>{/each}{#if !rows('alert').length}<div class="empty">Nenhum alerta registrado.</div>{/if}
 {:else if tab==='audit'}
 <section class="panel table-wrap"><table><thead><tr><th>Quando</th><th>Ator</th><th>Ação</th><th>Alvo / resultado</th></tr></thead><tbody>{#each audit as a}<tr><td>{stamp(a.created)}</td><td>{a.actor}</td><td>{a.action}</td><td>{a.target}<small>{a.result}</small></td></tr>{/each}</tbody></table></section>
  {:else if tab==='settings'}
  <div class="grid2"><section class="panel"><h2>GitHub App</h2><p class="muted">{settings.github_configured?'Configurada. Segredos não são retornados ao navegador.':'Configure a App e instale nas contas desejadas.'}</p><details open><summary>Passo a passo e permissões</summary><ol class="steps"><li>Crie uma GitHub App em Settings → Developer settings → GitHub Apps. Configure a Homepage para o painel e o webhook abaixo.</li><li>Eventos: <code>workflow_job</code>, <code>installation</code> e <code>installation_repositories</code>. Gere App ID, chave privada PEM e segredo de webhook com pelo menos 24 caracteres.</li><li>Permissões base de repositório: Metadata read, Contents read e Actions read. Para runners de repositório, acrescente Administration write.</li><li>Para organizações, habilite Self-hosted runners write. Para criar PRs de migração, acrescente Contents write, Workflows write e Pull requests write — são opcionais se você não usar essa função.</li><li>Salve os valores abaixo, instale a App nos repositórios desejados e vá a Repositórios → Atualizar instalações → Executar inventário.</li></ol><p class="warning">Conceda somente as permissões que pretende usar. A App cria/consulta runners; ela não garante que o GitHub atribua um job elegível à sua máquina.</p></details><form onsubmit={e=>{e.preventDefault();run(async()=>{await api('/github/app','PUT',{app_id:appID,private_key:appKey,webhook_secret:webhookSecret});appKey='';webhookSecret='';await reload();success='App configurada.'})}}><label>App ID<input bind:value={appID} required/></label><label>Chave privada PEM<textarea bind:value={appKey} rows="5" autocomplete="off" required></textarea></label><label>Segredo webhook<input type="password" bind:value={webhookSecret} minlength="24" required/></label><p class="muted">Webhook URL: {typeof location!=='undefined'?location.origin:''}/api/github/webhook</p><button class="primary" disabled={busy}>Salvar App</button></form></section><section class="panel"><h2>Segurança da conta</h2><p>TOTP: <b>{auth.totp_enabled?'Ativo':'Não configurado'}</b></p><button onclick={()=>run(async()=>{const v=await api('/auth/totp/start','POST',{});totpSecret=v.secret;success='Adicione o segredo ao autenticador e confirme o código.'})}>Configurar TOTP</button>{#if totpSecret}<label>Segredo — guarde no autenticador<input readonly value={totpSecret}/></label><label>Código<input bind:value={otp}/></label><button onclick={()=>run(async()=>{const v=await api('/auth/totp/enable','POST',{otp});recoveryCodes=v.recovery_codes;totpSecret='';otp='';auth.totp_enabled=true})}>Confirmar TOTP</button>{/if}{#if recoveryCodes.length}<p class="warning">Códigos exibidos uma única vez. Guarde fora do servidor.</p><pre>{recoveryCodes.join('\n')}</pre>{/if}<hr/><h3>Exportação</h3><a class="button" href="/api/export" download>Baixar dados de controle</a><p class="muted">Não inclui chaves privadas ou segredos.</p></section></div>
 <section class="panel"><h2>Retenção e operação</h2><form onsubmit={e=>{e.preventDefault();run(async()=>{const {github_configured,agent_url,backup_configured,...v}=settings;await api('/settings','PUT',v);success='Preferências salvas.'})}}><div class="grid3">{#each [['log_days','Logs (dias)'],['history_days','Histórico (dias)'],['audit_days','Auditoria (dias)'],['scan_days','Janela do inventário (dias)'],['scan_hours','Inventário periódico (horas)'],['org_max_slots','Teto por organização']] as [key,label]}<label>{label}<input type="number" min="1" bind:value={settings[key]}/></label>{/each}</div><div class="grid2"><label>Preço Linux por minuto (moeda escolhida)<input type="number" min="0" step="0.0001" bind:value={settings.linux_price_per_minute}/></label><label>Referência de preço e moeda<input bind:value={settings.price_reference}/></label></div><label>Webhook de alertas HTTPS (Discord suportado)<input bind:value={settings.alert_webhook}/></label><button class="primary" disabled={busy}>Salvar preferências</button></form></section>
 <section class="panel"><h2>Backups criptografados</h2><p class="muted">Snapshot online consistente. Frequência e retenção configuráveis. Bucket vazio salva localmente.</p><form onsubmit={e=>{e.preventDefault();configureBackup()}}><div class="grid2"><label>Endpoint S3/R2<input bind:value={backupEndpoint} placeholder="https://…"/></label><label>Bucket<input bind:value={backupBucket}/></label><label>Access key<input bind:value={backupAccess} autocomplete="off"/></label><label>Secret key<input type="password" bind:value={backupSecret}/></label></div><div class="grid2"><label>Intervalo (horas)<input type="number" min="1" bind:value={backupInterval}/></label><label>Retenção (dias)<input type="number" min="1" bind:value={backupRetention}/></label></div><label>Senha do backup<input type="password" minlength="12" bind:value={backupPassword} required/></label><div class="actions"><button class="primary" disabled={busy}>Configurar</button><button type="button" onclick={()=>action('/backups/run',{})}>Executar agora</button></div></form><p class="warning">A restauração também precisa do master.key e das chaves da CA. Consulte o recovery kit na documentação.</p>{#each rows('backup') as b}<div class="row"><span>{stamp(b.created)}</span><span>{b.status}</span><small>{b.error||b.location}</small></div>{/each}</section>
 {/if}
 <footer>Runner Fleet · Nenhum SSH público necessário · Dados reais da sua instalação</footer></main></div>
{/if}
{#if form}<div class="overlay"><section class="modal wide"><div class="toolbar"><h2>{form==='pool'?'Configurar pool':form==='machine'?'Configurar máquina':form==='ssh'?'Instalação por SSH privado':form==='enrollment'?'Cadastrar máquina':form==='migration'?'Revisar migração':form==='group'?'Grupo de runners':'Logs do job'}</h2><button onclick={()=>{form='';enrollment=null;sshKey='';rootPassword='';logs=''}}>×</button></div>
 {#if form==='pool'||form==='machine'}
  <label>Nome<input bind:value={editor.name}/></label>
  {#if form==='pool'}<p class="muted">Pool de organização exige grupo de runners restrito. Pool de repositório não usa grupo. Labels precisam corresponder a todas as labels em <code>runs-on</code>. {#if editor.execution==='service'}O runner oficial fica como serviço persistente no host, sem Docker.{:else}A imagem deve conter o runner oficial e as ferramentas do job, fixada por digest.{/if}</p>{/if}
 {#if form==='pool'}<div class="grid2"><label>Instalação GitHub<select bind:value={editor.installation}>{#each rows('installation') as i}<option value={i.id}>{i.owner} · #{i.id}</option>{/each}</select></label><label>Escopo<select bind:value={editor.scope}><option value="org">Organização</option><option value="repo">Repositório</option></select></label></div><label>{editor.scope==='org'?'Organização':'owner/repository'}<input bind:value={editor.target}/></label><div class="grid2"><label>Arquitetura<select bind:value={editor.arch}><option value="amd64">Linux x64</option><option value="arm64">Linux ARM64</option></select></label><label>Grupo de runners (opcional)<input bind:value={editor.group}/></label></div><label>Labels separadas por vírgula<input value={editor.labels?.join(', ')} oninput={e=>editor.labels=e.currentTarget.value.split(',').map(x=>x.trim()).filter(Boolean)}/></label><label>Execução<select bind:value={editor.execution} onchange={()=>{if(editor.execution==='service')editor.docker_sidecar=false}}><option value="container">Container efêmero</option><option value="service">Serviço persistente no host</option></select></label>{#if editor.execution==='service'}<label>Versão do actions/runner<input bind:value={editor.runner_version} placeholder="2.321.0" required/></label><label>SHA256 linux x64<input bind:value={editor.runner_sha256_amd64} required pattern="[0-9a-fA-F]{64}"/></label><label>SHA256 linux arm64<input bind:value={editor.runner_sha256_arm64} required pattern="[0-9a-fA-F]{64}"/></label>{:else}<label>Imagem de execução com digest<input bind:value={editor.image} required/></label>{/if}<label>Máquinas elegíveis<select multiple bind:value={editor.machines}>{#each rows('machine').filter(m=>!m.cloud_provider) as m}<option value={m.id}>{m.name} · {m.arch}</option>{/each}</select></label>
   <label><input class="check" type="checkbox" checked={!!editor.spot} onclick={toggleSpot}/> Habilitar provisionamento EC2 Spot para este pool</label>
   {#if editor.spot}<p class="warning">O Fleet cria e encerra EC2 e pode gerar custos. Requer permissões AWS no processo do servidor, AMI, subnets, security groups e instance profile configurados por você. Interrupções podem perder jobs ativos.</p><div class="grid2"><label>Região AWS<input bind:value={editor.spot.region} placeholder="us-east-1"/></label><label>AMI<input bind:value={editor.spot.image_id} placeholder="ami-..."/></label></div><label>Preparação da AMI<select bind:value={editor.spot.image_mode}><option value="bootstrap">Instalar no boot — pacotes apt, rpm ou zypper e Docker rootless</option><option value="prebaked">AMI preparada — agente/Docker já disponíveis</option></select></label><label>Subnets (IDs separadas por vírgula)<input value={editor.spot.subnet_ids.join(', ')} oninput={e=>editor.spot.subnet_ids=e.currentTarget.value.split(',').map((x:string)=>x.trim()).filter(Boolean)}/></label><label>Security groups (IDs separadas por vírgula)<input value={editor.spot.security_group_ids.join(', ')} oninput={e=>editor.spot.security_group_ids=e.currentTarget.value.split(',').map((x:string)=>x.trim()).filter(Boolean)}/></label><label>Instance profile IAM (nome ou ARN, opcional)<input bind:value={editor.spot.instance_profile}/></label><label>Tipos Spot permitidos (separados por vírgula)<input value={editor.spot.spot_instance_types.join(', ')} oninput={e=>editor.spot.spot_instance_types=e.currentTarget.value.split(',').map((x:string)=>x.trim()).filter(Boolean)}/></label><label>Tipos On-Demand de fallback (vazio desativa fallback)<input value={editor.spot.on_demand_instance_types.join(', ')} oninput={e=>editor.spot.on_demand_instance_types=e.currentTarget.value.split(',').map((x:string)=>x.trim()).filter(Boolean)}/></label><div class="grid3"><label>Slots por máquina<input type="number" min="1" max="32" bind:value={editor.spot.slots_per_machine}/></label><label>Máquinas Spot máximas<input type="number" min="1" max="100" bind:value={editor.spot.max_machines}/></label><label>Minutos ociosa antes de encerrar<input type="number" min="1" max="1440" bind:value={editor.spot.idle_minutes}/></label></div><div class="grid2"><label>Volume raiz (GiB)<input type="number" min="20" max="2048" bind:value={editor.spot.root_volume_gib}/></label><label>Segundos antes do fallback (0 desativa)<input type="number" min="0" max="3600" bind:value={editor.spot.fallback_after_seconds}/></label></div>{/if}<div class="grid3"><label>Slots mínimos<input type="number" min="0" bind:value={editor.min}/></label><label>Slots máximos<input type="number" min="1" bind:value={editor.max}/></label><label>Peso de capacidade<input type="number" min="1" bind:value={editor.weight}/></label></div>{#if editor.execution!=='service'}<label><input class="check" type="checkbox" bind:checked={editor.docker_sidecar}/> Docker isolado por job (somente máquina dedicada)</label>{#if editor.docker_sidecar}<label>Imagem do daemon Docker fixada por digest<input bind:value={editor.docker_image}/></label><p class="warning">Sidecar privilegiado dentro do Docker rootless. Reserve 2+ CPUs e 2048+ MB; execute canário antes de ativar.</p>{/if}{/if}<label><input class="check" type="checkbox" bind:checked={editor.enabled}/> Pool ativo</label><label><input class="check" type="checkbox" bind:checked={editor.trusted}/> Confirmo que este pool executará apenas código confiável</label>
 {:else}<label>Slots máximos da máquina<input type="number" min="1" bind:value={editor.max_slots}/></label><label><input class="check" type="checkbox" bind:checked={editor.shared}/> Máquina compartilhada com outros serviços</label><div class="grid3"><label>Fuso horário<input bind:value={editor.timezone}/></label><label>Hora inicial<input type="number" min="0" max="23" bind:value={editor.start_hour}/></label><label>Hora final<input type="number" min="0" max="23" bind:value={editor.end_hour}/></label></div><p class="muted">Horas iguais permitem execução em qualquer horário.</p>{/if}
 <div class="grid3"><label>{form==='pool'?'CPU por job':'CPU disponível'}<input type="number" min="0.1" step="0.1" bind:value={editor.cpu}/></label><label>Memória (MB)<input type="number" min="256" bind:value={editor.memory_mb}/></label><label>Orçamento de disco (MB)<input type="number" min="512" bind:value={editor.disk_mb}/></label></div><button class="primary" disabled={busy} onclick={saveForm}>Salvar configuração</button>
  {:else if form==='enrollment'&&enrollment}<p>Execute este fluxo no host Linux que vai receber os jobs (não no servidor do painel). Requisitos: systemd, cgroup v2 e saída HTTPS ao painel/GitHub. O nome é opcional; sem <code>RF_NAME</code>, usa o hostname.</p><label>Código — expira em 15 minutos e só pode ser usado uma vez<input readonly value={enrollment.code}/></label><p class="warning">Grave o código em um arquivo root-only (modo 0600), por exemplo com <code>sudoedit</code>. Não o cole em um comando, URL ou argumento de processo. A instalação remove a cópia usada pelo serviço, mas apague também o arquivo de origem após sucesso.</p><p>Com o arquivo-fonte do projeto no host, execute:</p><pre>sudo env RF_SERVER='{enrollment.server}' \
  RF_CODE_FILE=/root/runner-fleet-enrollment \
  RF_NAME=build-host sh scripts/install.sh
sudo sh scripts/setup-rootless-docker.sh
sudo rm -f /root/runner-fleet-enrollment</pre><p class="muted"><code>install.sh</code> instala os pacotes de runtime, o agente assinado e o serviço que gere runners persistentes. O script rootless continua separado e só é necessário para pools de container. Alternativamente, baixe <code>{enrollment.server}/downloads/install.sh</code> para o host e execute esse arquivo com as mesmas variáveis.</p><p>Validação: volte a Máquinas, aguarde o estado <code>online</code> e execute <b>Doctor</b>. Só ative um pool depois de “Doctor aprovado”.</p>
  {:else if form==='group'}<p class="muted">Cria um grupo no GitHub limitado aos repositórios privados selecionados. Use o nome no pool da organização.</p><label>Organização<input bind:value={groupOrganization}/></label><label>Nome do grupo<input bind:value={groupName}/></label><label>Repositórios permitidos<select multiple bind:value={groupRepos}>{#each rows('repository').filter(r=>r.installation===Number(selectedInstallation)&&r.private) as r}<option value={r.id}>{r.full_name}</option>{/each}</select></label><button class="primary" disabled={busy||!groupRepos.length} onclick={()=>run(async()=>{await api('/github/groups','POST',{installation:Number(selectedInstallation),organization:groupOrganization,name:groupName,repositories:groupRepos});form='';success='Grupo criado; inventário solicitado.'})}>Criar grupo no GitHub</button>
  {:else if form==='ssh'}<p class="muted">Instalação remota iniciada pelo painel: use somente IP privado/Tailscale. O servidor precisa alcançar a porta SSH; confirme o fingerprint SHA256 fora de banda. A chave privada e a senha de root são usadas nesta requisição e não são persistidas. O usuário pode ser root, ter <code>sudo -n</code>, ou informar a senha para <code>su -</code>. Pools de container ainda precisam de Docker rootless para <code>fleet-agent</code>; este fluxo não cria uma EC2 nem instala Docker rootless.</p><form onsubmit={e=>{e.preventDefault();const secret=rootPassword;rootPassword='';run(async()=>{await api('/bootstrap/ssh','POST',{host:sshHost,port:22,user:sshUser,private_key:sshKey,root_password:secret,fingerprint,name:machineName});sshKey='';form='';success='Agente instalado. Verifique estado online e Doctor em Máquinas.'})}}><div class="grid2"><label>IP privado<input bind:value={sshHost} required/></label><label>Usuário SSH<input bind:value={sshUser} required/></label></div><label>Nome da máquina<input bind:value={machineName} required/></label><label>Fingerprint SHA256 do host<input bind:value={fingerprint} required/></label><label>Chave privada SSH temporária<textarea rows="5" bind:value={sshKey} required></textarea></label><label>Senha de root para su - (opcional)<input type="password" bind:value={rootPassword} autocomplete="off"/></label><button class="primary" disabled={busy}>Instalar agente</button></form>
 {:else if form==='migration'&&migrationPreview}<p class="warning">Revise o destino e confirme capacidade antes de criar o PR.</p><div class="grid2"><div><h3>Antes</h3><pre>{migrationPreview.before}</pre></div><div><h3>Depois</h3><pre>{migrationPreview.after}</pre></div></div><button class="primary" disabled={busy} onclick={createPR}>Criar PR com esta alteração</button>
 {:else if form==='logs'}<pre>{logs}</pre>{/if}{#if error}<p class="error">{error}</p>{/if}</section></div>{/if}
{#if elevation}<div class="overlay"><section class="modal"><h2>Confirmar identidade</h2><p class="muted">Necessário para segredos, cadastro de máquinas e operações sensíveis.</p><form onsubmit={e=>{e.preventDefault();reauth()}}><label>Senha<input type="password" bind:value={elevatedPassword} required/></label><label>TOTP / recuperação<input bind:value={elevatedOTP}/></label><div class="actions"><button class="primary" disabled={busy}>Confirmar</button><button type="button" onclick={()=>elevation=false}>Cancelar</button></div>{#if error}<p class="error">{error}</p>{/if}</form></section></div>{/if}
<style>
 :global(*){box-sizing:border-box} :global(body){margin:0;font:14px/1.55 system-ui,sans-serif;color:#1d2939;background:#f5f7fb}:global(button),:global(input),:global(textarea),:global(select){font:inherit}:global(button),.button{border:1px solid #d8dfeb;background:white;padding:9px 14px;border-radius:9px;cursor:pointer;color:#344054;text-decoration:none;display:inline-block}:global(button:hover){background:#edf2f9}:global(button:disabled){opacity:.55;cursor:wait}.primary{background:#2963ed;color:white;border-color:#2963ed}.primary:hover{background:#1e50cb}.danger{color:#b42318}:global(input),:global(textarea),:global(select){width:100%;padding:10px 12px;border:1px solid #d4dce9;border-radius:8px;background:white;color:#1d2939}:global(input:focus),:global(textarea:focus){outline:2px solid #9cbafa}:global(label){display:block;font-weight:600;margin:12px 0}:global(label input),:global(label textarea){display:block;margin-top:6px}:global(h1){font-size:30px;line-height:1.2;margin:6px 0 0;letter-spacing:-1px}:global(h2){font-size:18px;line-height:1.4;margin:0 0 12px;letter-spacing:-.3px}:global(h3){font-size:15px}:global(small){display:block;color:#667085;font-size:12px}:global(a){color:#285fd4}:global(pre){white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f6fa;padding:15px;border-radius:8px;font-size:12px;max-height:500px;overflow:auto}:global(hr){border:0;border-top:1px solid #e6ebf2;margin:24px 0}.muted{color:#667085}.eyebrow{font-size:10px;letter-spacing:1.6px;font-weight:700;color:#6c7b91;margin:0}.brand{font-size:20px;font-weight:750;display:flex;align-items:center;gap:10px}.brand-icon{font-size:12px;letter-spacing:-.5px;background:#3069f2;color:white;border-radius:10px;padding:10px 9px}.shell{display:flex;min-height:100vh}aside{width:235px;position:fixed;inset:0 auto 0 0;background:#101828;color:#eef4ff;padding:28px 18px;display:flex;flex-direction:column}.workspace{font-size:9px;letter-spacing:1.8px;color:#8392ac;margin:15px 12px 32px}nav{display:flex;flex